const cfg = $('Config').item.json;
const b = $json.body || $json || {};
const jobId = String(b.jobId || b.job_id || $execution.id);
const callbackUrl = String(b.callbackUrl || b.callback_url || '').trim();
let contentType = String(b.contentType || b.content_type || 'image').toLowerCase();
if (!['image', 'carousel', 'video'].includes(contentType)) contentType = 'image';

const IMG_RATIOS = ['1:1', '9:16', '16:9', '3:4', '4:3', '4:5'];
const VID_RATIOS = ['9:16', '16:9'];
let aspectRatio = String(b.aspectRatio || b.aspect_ratio || '').trim();
if (contentType === 'video') { if (!VID_RATIOS.includes(aspectRatio)) aspectRatio = '9:16'; }
else { if (!IMG_RATIOS.includes(aspectRatio)) aspectRatio = '1:1'; }
const ratioDesc = { '1:1': 'square 1:1 composition', '9:16': 'vertical portrait 9:16', '16:9': 'horizontal widescreen 16:9', '3:4': 'portrait 3:4', '4:3': 'landscape 4:3', '4:5': 'portrait 4:5' }[aspectRatio] || aspectRatio;

let videoDuration = parseInt(b.videoDuration || b.video_duration || 8, 10);
if (![8, 16, 32, 48].includes(videoDuration)) videoDuration = 8;
const segments = videoDuration / 8;

const prompt = String(b.prompt || b.image_prompt || b.video_prompt || b.idea || '').trim();
const prompts = Array.isArray(b.prompts) ? b.prompts.map(String) : [];
let carouselCount = parseInt(b.carouselCount || b.carousel_count || (prompts.length || 4), 10);
carouselCount = Math.max(2, Math.min(10, carouselCount));

return { json: {
  jobId, callbackUrl, contentType,
  campaign: b.campaign || '', idea: b.idea || '', caption: b.caption || '',
  aspectRatio, ratioDesc, videoDuration, segments,
  prompt, prompts, carouselCount,
  gcsBucket: cfg.gcsBucket, gcsPrefix: cfg.gcsPrefix, filesDir: cfg.filesDir,
  receivedAt: new Date().toISOString()
} };

const norm = $('Normalize Input').item.json;
const g = $input.item.json || {};
const bin = $input.item.binary || {};
const um = g.usageMetadata || {};
let inTok = Number(um.promptTokenCount || 0);
let outTok = Number(um.candidatesTokenCount || 0);
let estimated = false;
if (!inTok && !outTok) { inTok = Math.ceil(String(norm.prompt || '').length / 4); outTok = 1290; estimated = true; }
const img = bin.content;
const ext = (img && img.fileExtension) || 'png';
return { json: {
  contentKind: 'image', ok: !!img,
  gcsObject: norm.gcsPrefix + '/' + norm.jobId + '/image.' + ext,
  mimeType: (img && img.mimeType) || 'image/png',
  tokenSteps: [{ step: 'image', input: inTok, output: outTok, estimated }],
  errorMsg: img ? null : String(g.error || 'image generation failed')
}, binary: img ? { content: img } : {} };

const norm = $('Normalize Input').first().json;
const N = norm.carouselCount;
const out = [];
for (let i = 0; i < N; i++) {
  const p = norm.prompts[i] || (norm.prompt + ' — variasi slide ' + (i + 1) + ' dari ' + N + ', konsisten gaya, warna, dan subjek antar slide');
  out.push({ json: { ...norm, slideIndex: i + 1, slideTotal: N, slidePrompt: String(p) } });
}
return out;

const norm = $('Normalize Input').first().json;
const items = $input.all();
const out = [];
let n = 0;
items.forEach((it, idx) => {
  const b = it.binary || {};
  const g = it.json || {};
  if (!b.slide) return;
  n++;
  const um = g.usageMetadata || {};
  let inTok = Number(um.promptTokenCount || 0);
  let outTok = Number(um.candidatesTokenCount || 0);
  let estimated = false;
  if (!inTok && !outTok) { inTok = Math.ceil(String(norm.prompt || '').length / 4); outTok = 1290; estimated = true; }
  const ext = b.slide.fileExtension || 'png';
  out.push({ json: {
    contentKind: 'carousel', ok: true, slideIndex: n,
    gcsObject: norm.gcsPrefix + '/' + norm.jobId + '/slide_' + String(n).padStart(2, '0') + '.' + ext,
    mimeType: b.slide.mimeType || 'image/png',
    tokenSteps: [{ step: 'carousel_' + n, input: inTok, output: outTok, estimated }]
  }, binary: { content: b.slide } });
});
if (out.length === 0) return [{ json: { contentKind: 'carousel', ok: false, tokenSteps: [], errorMsg: 'carousel generation failed' }, binary: {} }];
return out;

