const norm = $('Normalize Input').first().json;
const raw = $input.first().json || {};
let txt = raw;
if (txt && typeof txt === 'object') {
  if (txt.content && typeof txt.content === 'object' && Array.isArray(txt.content.parts)) txt = txt.content.parts.map(p => (p && p.text) || '').join('');
  else if (typeof txt.content === 'string') txt = txt.content;
  else if (Array.isArray(txt.parts)) txt = txt.parts.map(p => (p && p.text) || '').join('');
  else if (typeof txt.text === 'string') txt = txt.text;
  else if (Array.isArray(txt.candidates)) { const c = txt.candidates[0]; txt = (c && c.content && c.content.parts && c.content.parts.map(p => (p && p.text) || '').join('')) || JSON.stringify(txt); }
}
let plan = {};
if (typeof txt === 'string') { try { plan = JSON.parse(txt.replace(/```json/gi, '').replace(/```/g, '').trim()); } catch (e) { plan = {}; } }
else if (txt && typeof txt === 'object') plan = txt;
const N = norm.segments;
let scenes = Array.isArray(plan.scenes) ? plan.scenes.map(String) : [];
while (scenes.length < N) scenes.push(norm.prompt);
scenes = scenes.slice(0, N);
const um = raw.usageMetadata || {};
const pIn = Number(um.promptTokenCount || 0);
const pOut = Number((um.candidatesTokenCount || 0) + (um.thoughtsTokenCount || 0)) || Number((um.totalTokenCount || 0) - pIn) || 0;
return scenes.map((sc, i) => ({ json: {
  ...norm, sceneIndex: i + 1, sceneTotal: N, scenePrompt: sc,
  planInput: i === 0 ? pIn : 0, planOutput: i === 0 ? pOut : 0
} }));

const norm = $('Normalize Input').first().json;
const rid = norm.jobId;
const n = $('Parse Scenes').all().length;
const DIR = norm.filesDir;
const files = [];
for (let i = 1; i <= n; i++) files.push('gen_' + rid + '_' + String(i).padStart(3, '0') + '.mp4');
const finalPath = DIR + '/gen_' + rid + '_final.mp4';
const listPath = 'gen_' + rid + '_list.txt';
const cmd = 'mkdir -p ' + DIR + ' && cd ' + DIR + ' && FF="$(command -v ffmpeg || echo ffmpeg)" && printf "file \'%s\'\\n" ' + files.join(' ') + ' > ' + listPath + ' && "$FF" -y -f concat -safe 0 -i ' + listPath + ' -c:v libx264 -pix_fmt yuv420p -c:a aac -movflags +faststart ' + finalPath + ' 2>&1 | tail -4; echo EXIT=$?';
return [{ json: { ...norm, sceneCount: n, finalPath, concatCmd: cmd } }];

const norm = $('Normalize Input').first().json;
let vid = null;
try { vid = ($('Read Final Video').first().binary || {}).content || null; } catch (e) { vid = null; }
const steps = [];
try {
  const p = $('Parse Scenes').all();
  const p0 = (p[0] && p[0].json) || {};
  if (p0.planInput || p0.planOutput) steps.push({ step: 'plan', input: p0.planInput || 0, output: p0.planOutput || 0 });
} catch (e) {}
steps.push({ step: 'veo', input: 0, output: 0, videoSeconds: norm.videoDuration, note: 'Veo dihitung per-detik' });
return { json: {
  contentKind: 'video', ok: !!vid,
  gcsObject: norm.gcsPrefix + '/' + norm.jobId + '/video.mp4',
  mimeType: 'video/mp4',
  tokenSteps: steps,
  errorMsg: vid ? null : 'video generation/concat failed'
}, binary: vid ? { content: vid } : {} };

const norm = $('Normalize Input').first().json;
const ct = norm.contentType;
const base = 'https://storage.googleapis.com/' + norm.gcsBucket + '/';
const gcs = $input.all();

function urlOf(g) { const name = g && (g.name || (g.json && g.json.name)); return name ? (base + name) : null; }
function gsOf(g) { const j = g.json || g; return (j && j.bucket && j.name) ? ('gs://' + j.bucket + '/' + j.name) : null; }

let collectData = [];
try {
  if (ct === 'image') collectData = $('Collect Image').all();
  else if (ct === 'carousel') collectData = $('Collect Carousel').all();
  else collectData = $('Collect Video').all();
} catch (e) {}
let steps = [];
collectData.forEach(it => { if (it.json && Array.isArray(it.json.tokenSteps)) steps = steps.concat(it.json.tokenSteps); });

let content = null;
if (ct === 'carousel') {
  const slides = gcs.map(g => { const j = g.json || g; const u = urlOf(j); return u ? { url: u, gsUri: gsOf(j), mimeType: j.contentType || 'image/png', bytes: Number(j.size) || null } : null; }).filter(Boolean);
  if (slides.length) content = { kind: 'carousel', count: slides.length, slides };
} else {
  const j = (gcs[0] && (gcs[0].json || gcs[0])) || {};
  const u = urlOf(j);
  if (u) content = { kind: ct, url: u, gsUri: gsOf(j), mimeType: j.contentType || (ct === 'video' ? 'video/mp4' : 'image/png'), bytes: Number(j.size) || null };
}

const inTok = steps.reduce((a, s) => a + Number(s.input || 0), 0);
const outTok = steps.reduce((a, s) => a + Number(s.output || 0), 0);
const total = inTok + outTok;
const estimated = steps.some(s => s.estimated);
const ok = !!content;
const errFromCollect = (collectData.find(it => it.json && it.json.errorMsg) || { json: {} }).json.errorMsg;

const payload = {
  jobId: norm.jobId, status: ok ? 'success' : 'failed', contentType: ct,
  campaign: norm.campaign, idea: norm.idea, caption: norm.caption, aspectRatio: norm.aspectRatio,
  videoDuration: ct === 'video' ? norm.videoDuration : null,
  content,
  tokens: { input: inTok, output: outTok, total, estimated, byStep: steps },
  restoreTokens: !ok, restoreAmount: ok ? 0 : total,
  error: ok ? null : (errFromCollect || 'generation or GCS upload failed'),
  generatedAt: new Date().toISOString()
};
return [{ json: { callbackUrl: norm.callbackUrl, payload } }];
